Script.script:
function uiSetup()
  if uiSetupInProgress then
    return
  end
  timeframe("uiSetupInProgress", 0, 0.5)
  GUI = GUI or {}
  GUI.RetroMUD_UI_Right = GUI.RetroMUD_UI_Right or Adjustable.Container:new(
      {
        name = "RetroMUD_UI_Right",
        y = "0%",
        height = "100%",
        x = "-30%",
        width = "30%",
        locked = true,
        autoLoad = false,
      }
    )
  GUI.RetroMUD_UI_Bottom = GUI.RetroMUD_UI_Bottom or Adjustable.Container:new(
      {
        name = "RetroMUD_UI_Bottom",
        y = "-60px",
        height = "60px",
        x = "0%",
        width = "60%",
        locked = true,
        autoLoad = false,
        adjLabelstyle = "border: 5px groove grey;",
      }
    )
  GUI.RetroMUD_UI_Bottom:attachToBorder("bottom")
  GUI.RetroMUD_UI_Right:attachToBorder("right")
  GUI.RetroMUD_UI_Bottom:connectToBorder("right")
  hpbar = hpbar or Geyser.Gauge:new(
      {name = "hpbar", x = "20px", y = 0, width = "280px", height = "50px"}, GUI.RetroMUD_UI_Bottom
    )
  hpbar.front:setStyleSheet(
    [[background-color: QLinearGradient( x1: 0, y1: 0, x2: 0, y2: 1, stop: 0 #f04141, stop: 0.1 #ef2929, stop: 0.49 #cc0000, stop: 0.5 #a40000, stop: 1 #cc0000);
    border-top: 1px black solid;
    border-left: 1px black solid;
    border-bottom: 1px black solid;
    border-radius: 7;
    padding: 3px;]]
  )
  hpbar.back:setStyleSheet(
    [[background-color: QLinearGradient( x1: 0, y1: 0, x2: 0, y2: 1, stop: 0 #bd3333, stop: 0.1 #bd2020, stop: 0.49 #990000, stop: 0.5 #700000, stop: 1 #990000);
    border-width: 1px;
    border-color: black;
    border-style: solid;
    border-radius: 7;
    padding: 3px;]]
  )
  spbar = spbar or Geyser.Gauge:new(
      {name = "spbar", x = "320px", y = 0, width = "280px", height = "50px"}, GUI.RetroMUD_UI_Bottom
    )
  spbar.front:setStyleSheet(
    [[background-color: QLinearGradient( x1: 0, y1: 0, x2: 0, y2: 1, stop: 0 #4141f0, stop: 0.1 #2929ef, stop: 0.49 #0000cc, stop: 0.5 #0000a4, stop: 1 #0000bb);
    border-top: 1px black solid;
    border-left: 1px black solid;
    border-bottom: 1px black solid;
    border-radius: 7;
    padding: 3px;
    fontSize: 14]]
  )
  spbar.back:setStyleSheet(
    [[background-color: QLinearGradient( x1: 0, y1: 0, x2: 0, y2: 1, stop: 0 #3333bd, stop: 0.1 #2020bd, stop: 0.49 #000099, stop: 0.5 #000070, stop: 1 #000099);
    border-width: 1px;
    border-color: black;
    border-style: solid;
    border-radius: 7;
    padding: 3px;
    fontSize: 14
    ]]
  )
  epbar = epbar or Geyser.Gauge:new(
      {name = "epbar", x = "620px", y = 0, width = "280px", height = "50px"}, GUI.RetroMUD_UI_Bottom
    )
  epbar.front:setStyleSheet(
    [[background-color: QLinearGradient( x1: 0, y1: 0, x2: 0, y2: 1, stop: 0 #98f041, stop: 0.1 #8cf029, stop: 0.49 #66cc00, stop: 0.5 #52a300, stop: 1 #66cc00);
    border-top: 1px black solid;
    border-left: 1px black solid;
    border-bottom: 1px black solid;
    border-radius: 7;
    padding: 3px;
    fontSize: 14
]]
  )
  epbar.back:setStyleSheet(
    [[background-color: QLinearGradient( x1: 0, y1: 0, x2: 0, y2: 1, stop: 0 #78bd33, stop: 0.1 #6ebd20, stop: 0.49 #4c9900, stop: 0.5 #387000, stop: 1 #4c9900);
    border-width: 1px;
    border-color: black;
    border-style: solid;
    border-radius: 7;
    padding: 3px;
    fontSize: 14
]]
  )
  hpbar:setFontSize(14)
  spbar:setFontSize(14)
  epbar:setFontSize(14)
  hpbar:setValue(math.random(1, 100), 100, "<b><center>HP not yet captured</center></b>")
  spbar:setValue(math.random(1, 100), 100, "<b><center>SP not yet captured</center></b>")
  epbar:setValue(math.random(1, 100), 100, "<b><center>EP not yet captured</center></b>")
  infolabel = infolabel or Geyser.Label:new(
      {
        name = "infolabel",
        x = "10px",
        y = "0px",
        width = "100%-20px",
        height = "140px",
        message = [[<b><top>Infobox not yet intialized.</top></b>]],
      },
      GUI.RetroMUD_UI_Right
    )
  infolabel:setStyleSheet(
    [[
  qproperty-alignment: 'AlignTop';
  qproperty-wordWrap: true;
  background-color: black;
  ]]
  )
  infolabel:setFontSize(14)
  setWindowWrap("main", getColumnCount("main"))
  oldWidth = oldWidth or 0
  if (oldWidth ~= getColumnCount("main")) then
    send("set WIDTH " .. getColumnCount("main"))
    oldWidth = getColumnCount("main")
  end
  tellsCon = tellsCon or Geyser.MiniConsole:new(
      {x = "0", y = "140px", height = "50%-140px", width = "100%"}, GUI.RetroMUD_UI_Right
    )
end
